import sys
def solve(words):
    from collections import defaultdict, deque
    chars = set("".join(words))
    graph = defaultdict(set)
    in_degree = {c: 0 for c in chars}
    for i in range(len(words) - 1):
        w1, w2 = words[i], words[i+1]
        for c1, c2 in zip(w1, w2):
            if c1 != c2:
                if c2 not in graph[c1]:
                    graph[c1].add(c2); in_degree[c2] += 1
                break
        else:
            if len(w1) > len(w2): return "INVALID"
    q = deque(sorted(c for c in chars if in_degree[c] == 0))
    result = []
    while q:
        c = q.popleft(); result.append(c)
        for nb in sorted(graph[c]):
            in_degree[nb] -= 1
            if in_degree[nb] == 0: q.append(nb)
    if len(result) < len(chars): return "CYCLE"
    return "".join(result)

if __name__ == '__main__':
    input_data = sys.stdin.read().splitlines()
    n = int(input_data[0].strip())
    words = [input_data[i+1].strip() for i in range(n)]
    print(solve(words))

